{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Inadequate sampling and representation of genetic diversity are widely recognized as a significant bias inherent in genomic databases, which has direct implications for the healthcare available to minority populations (Perera 2019).",
      "reason": "The Introduction describes the current state of genomic knowledge and key uncertainties, including underrepresentation of Indigenous populations in genomic databases and limited culturally safe genomic services."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "To begin to understand the possible contributions of precision medicine approaches to Indigenous populations, it is necessary to review extant research in this space and determine the scope for pharmacogenomics and genomics research.",
      "reason": "The Introduction explicitly explains the need and importance of conducting the review in the context of health disparities and limited Indigenous inclusion in genomics research."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_6",
      "quote": "No literature or systematic reviews were included in the results of this systematic review.",
      "reason": "No evidence of prior similar systematic reviews is reported; the Introduction does not cite previous reviews of pharmacogenomics in Indigenous populations, so the conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of the scope of pharmacogenomics/genomics research (including perspectives), not a review of intervention effects, so a mechanism of action description is not required."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not evaluate complex interventions or delivery contexts; no logic model requirement applies."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "This systematic review aimed to synthesize global empirical evidence involving Indigenous populations for genomics research with a particular focus on pharmacogenomics. The overarching intent of this review is to provide insight regarding how research has been conducted, the role of Indigenous participants in such research, and the benefits or outcomes achieved for Indigenous participants and/or communities.",
      "reason": "The objectives are explicitly stated in the Aims section (and echoed in the abstract), but they are not framed using a recognized question-formulation framework (e.g., PICO/SPIDER/PICo); PICO is only mentioned as guiding the search strategy (text_26), not the review questions."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_4",
      "quote": "This systematic review aimed to synthesize global empirical evidence involving Indigenous populations for genomics research with a particular focus on pharmacogenomics.",
      "reason": "This is a mixed-methods evidence synthesis of the scope of genomics/pharmacogenomics research (including qualitative perspectives), not a review of intervention effects, so planned intervention comparisons in PICO form do not apply."
    }
  ],
  "confidence": 85
}

{
